import {buildDawgModel,modelTriangles} from './dawg-model.js';
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
const cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const dot=(a,b)=>a[0]*b[0]+a[1]*b[1]+a[2]*b[2];
export function drawShowroom(c,model,{width=840,height=900,yaw=-.35,pitch=.07,zoom=1,time=0,animation='still',triangles=null,transparent=false,lighting='neon'}={}){
 c.save();c.setTransform(1,0,0,1,0,0);c.clearRect(0,0,width,height);const unit=Math.min(width,height),floor=height*.51+.96*Math.cos(pitch)*unit*1.43*zoom/(4+.96*Math.sin(pitch));if(!transparent){const bg=c.createLinearGradient(0,0,width,height);const palette=lighting==='gallery'?['#484858','#2c3340','#171e2b']:lighting==='sunset'?['#53314b','#38283a','#1b182c']:['#30223e','#151e32','#091322'];bg.addColorStop(0,palette[0]);bg.addColorStop(.55,palette[1]);bg.addColorStop(1,palette[2]);c.fillStyle=bg;c.fillRect(0,0,width,height);c.strokeStyle='#c4a5fa16';c.lineWidth=1;for(let i=-6;i<=6;i++){c.beginPath();c.moveTo(width/2+i*unit*.1,height*.49);c.lineTo(width/2+i*unit*.4,height);c.stroke();}for(let i=0;i<8;i++){const y=height*.53+Math.pow(i/7,2)*height*.48;c.beginPath();c.moveTo(0,y);c.lineTo(width,y);c.stroke();}
 c.fillStyle='#00000055';c.beginPath();c.ellipse(width/2,floor,unit*.24,unit*.055,0,0,Math.PI*2);c.fill();c.strokeStyle='#b0f2d456';c.lineWidth=2;c.beginPath();c.ellipse(width/2,floor,unit*.29,unit*.075,0,0,Math.PI*2);c.stroke();}
 const cy=Math.cos(yaw),sy=Math.sin(yaw),cp=Math.cos(pitch),sp=Math.sin(pitch),project=v=>{const x=v[0]*cy+v[2]*sy,z=-v[0]*sy+v[2]*cy,y=v[1]-.96,vy=y*cp-z*sp,vz=y*sp+z*cp,depth=4-vz,f=unit*1.43*zoom/depth;return {screen:[width/2+x*f,height*.51-vy*f],view:[x,vy,vz],depth};},faces=[];
 for(const tri of triangles||modelTriangles(model,time,animation)){const p=tri.vertices.map(project),vs=p.map(p=>p.view),a=vs[1].map((v,i)=>v-vs[0][i]),b=vs[2].map((v,i)=>v-vs[0][i]),n=cross(a,b),length=Math.hypot(...n);if(length<1e-10)continue;const center=vs[0].map((v,i)=>(v+vs[1][i]+vs[2][i])/3);if(dot(n,[-center[0],-center[1],4-center[2]])<=0)continue;const light=clamp(.38+.62*Math.max(0,dot(n.map(v=>v/length),[-.45,.6,.66])),.2,1);faces.push({p:p.map(p=>p.screen),depth:p.reduce((n,p)=>n+p.depth,0)/3,material:tri.material,light});}
 faces.sort((a,b)=>b.depth-a.depth);for(const {p,material:m,light}of faces){const shine=m.metallic*.12,color=m.color.slice(0,3).map((v,i)=>Math.round(clamp(v*light+shine+(m.emissive?.[i]||0),0,1)*255));c.fillStyle=`rgba(${color[0]},${color[1]},${color[2]},${m.color[3]})`;c.beginPath();c.moveTo(...p[0]);c.lineTo(...p[1]);c.lineTo(...p[2]);c.closePath();c.fill();c.strokeStyle=c.fillStyle;c.lineWidth=.55;c.stroke();}
 if(!transparent){c.fillStyle='#d5efac';c.font=`bold ${Math.round(unit*.022)}px sans-serif`;c.textAlign='left';c.fillText('DAWG / ATELIER',unit*.05,unit*.065);c.fillStyle='#b2aac6';c.font=`${Math.round(unit*.015)}px monospace`;c.fillText('3D ASSET · '+model.nodes.filter(n=>n.geometry).length+' MODULAR PARTS',unit*.05,unit*.095);c.textAlign='center';c.fillStyle='#aaa0be';c.fillText('DRAG TO ROTATE  ·  SCROLL / ZOOM  ·  ARROW KEYS',width/2,height-unit*.035);}c.restore();return {visibleTriangles:faces.length};
}
export class DawgShowroom {
 constructor(canvas){this.canvas=canvas;this.c=canvas.getContext('2d');this.yaw=-.35;this.pitch=.07;this.zoom=1;this.animation='still';this.visible=false;this.auto=false;this.pending=false;this.time=0;this.last=0;this.pointer=null;this.lighting='neon';this.quality='full';this.gpuState='canvas';document.addEventListener('visibilitychange',()=>{this.last=0;if(!document.hidden)this.loop();});
 canvas.addEventListener('pointerdown',e=>{if(this.pointer)return;e.preventDefault();this.pointer={id:e.pointerId,x:e.clientX,y:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(this.pointer?.id!==e.pointerId)return;this.yaw+=(e.clientX-this.pointer.x)*.012;this.pitch=clamp(this.pitch+(e.clientY-this.pointer.y)*.006,-.2,.4);this.pointer.x=e.clientX;this.pointer.y=e.clientY;this.draw();});const end=e=>{if(this.pointer?.id===e.pointerId)this.pointer=null;};for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,end);
 canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoom=clamp(this.zoom-e.deltaY*.001,.7,1.45);this.draw();},{passive:false});canvas.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','+','-','='].includes(e.key)){e.preventDefault();e.stopPropagation();if(e.key==='Home')this.reset();else if(['ArrowLeft','ArrowRight'].includes(e.key))this.yaw+=e.key==='ArrowLeft'?-.16:.16;else if(['ArrowUp','ArrowDown'].includes(e.key))this.pitch=clamp(this.pitch+(e.key==='ArrowUp'?-.05:.05),-.2,.4);else this.zoom=clamp(this.zoom+(e.key==='-'?-.07:.07),.7,1.45);this.draw();}});
 }
 set(d){this.dawg=d;this.model=buildDawgModel(d);this.still=modelTriangles(this.model);if(this.gpu){try{this.gpu.set(d);}catch{this.failGPU();}}this.draw();this.upgrade();}
 async upgrade(){if(this.gpuState!=='canvas'||typeof WebGL2RenderingContext==='undefined'||!this.canvas.parentElement)return;this.gpuState='loading';this.status('Loading GPU studio…');let target;try{const {GPUShowroom}=await import('./dawg-gpu.js');target=document.createElement('canvas');target.className='atelier-gpu';target.setAttribute('aria-hidden','true');this.canvas.parentElement.append(target);this.gpu=new GPUShowroom(target,()=>this.failGPU());this.gpu.set(this.dawg);this.gpu.lighting(this.lighting);this.gpuState='ready';this.draw();if(this.gpu&&this.gpuState==='ready'){this.canvas.style.opacity='0';this.status(this.quality==='light'?'3D STUDIO · LIGHT / BATTERY':'3D STUDIO · FULL DETAIL');}}catch{target?.remove();this.failGPU();}}
 status(text){this.onStatus?.(text);}
 failGPU(){this.gpuState='failed';try{this.gpu?.dispose();}catch{}this.gpu?.canvas.remove();this.gpu=null;this.canvas.style.opacity='1';this.status('CANVAS STUDIO · COMPATIBILITY MODE');this.draw();}
 setLighting(name){this.lighting=name;this.gpu?.lighting(name);this.draw();}
 setQuality(value){this.quality=value==='light'?'light':'full';if(this.gpu)this.status(this.quality==='light'?'3D STUDIO · LIGHT / BATTERY':'3D STUDIO · FULL DETAIL');this.draw();}

 reset(){this.yaw=-.35;this.pitch=.07;this.zoom=1;this.draw();}
 setVisible(on){this.visible=on;if(on)this.loop();}
 setAnimation(value){this.animation=['still','idle','walk','run'].includes(value)?value:'still';this.time=0;this.draw();this.loop();}
 draw(){if(this.gpu){try{this.gpu.render(this);return;}catch{this.failGPU();return;}}if(this.model)drawShowroom(this.c,this.model,{width:this.canvas.width,height:this.canvas.height,yaw:this.yaw,pitch:this.pitch,zoom:this.zoom,lighting:this.lighting,time:this.time,animation:this.animation==='run'?'walk':this.animation,triangles:this.animation==='still'?this.still:null});}
 loop(){if(!this.visible||this.pending||!this.auto&&this.animation==='still'||typeof requestAnimationFrame!=='function')return;this.pending=true;requestAnimationFrame(now=>{this.pending=false;if(!this.visible||document.hidden){this.last=0;return;}if(this.last&&now-this.last<33){this.loop();return;}const dt=this.last?Math.min(.06,(now-this.last)/1000):0;this.last=now;this.time+=dt;if(this.auto)this.yaw+=dt*.35;this.draw();this.loop();});}
}

export function drawSpriteAtlas(canvas,d,frameWidth=256,frameHeight=320){canvas.width=frameWidth*4;canvas.height=frameHeight*2;const c=canvas.getContext('2d'),model=buildDawgModel(d),triangles=modelTriangles(model);const temp=document.createElement('canvas');temp.width=frameWidth;temp.height=frameHeight;const context=temp.getContext('2d');for(let i=0;i<8;i++){drawShowroom(context,model,{width:frameWidth,height:frameHeight,yaw:i*Math.PI/4,pitch:.03,zoom:1.18,transparent:true,triangles});c.drawImage(temp,(i%4)*frameWidth,Math.floor(i/4)*frameHeight);}return {format:'dawg-3d-turntable',version:1,frameWidth,frameHeight,columns:4,rows:2,frames:Array.from({length:8},(_,i)=>({index:i,yawDegrees:i*45,x:i%4*frameWidth,y:Math.floor(i/4)*frameHeight,width:frameWidth,height:frameHeight}))};}
